from fastmcp import Server
from typing import Any
import inspect


def create_proxy_server(backend_server: Server, proxy_name: str = "proxy") -> Server:
    """
    Create a transparent proxy server that forwards all tool and resource
    requests to a backend FastMCP server instance.

    Args:
        backend_server: The backend FastMCP Server instance to proxy to
        proxy_name: Name for the proxy server (default: "proxy")

    Returns:
        A new FastMCP Server that transparently proxies all requests
    """
    proxy = Server(proxy_name)

    # Proxy all tools from backend
    if hasattr(backend_server, '_tools'):
        for tool_name, tool_func in backend_server._tools.items():
            def make_tool_forwarder(backend_func, name):
                async def forward_tool(**kwargs) -> Any:
                    if inspect.iscoroutinefunction(backend_func):
                        return await backend_func(**kwargs)
                    return backend_func(**kwargs)
                forward_tool.__name__ = name
                return forward_tool

            proxy.tool()(make_tool_forwarder(tool_func, tool_name))

    # Proxy all resources from backend
    if hasattr(backend_server, '_resources'):
        for resource_uri, resource_func in backend_server._resources.items():
            def make_resource_forwarder(backend_func, uri):
                async def forward_resource() -> str:
                    if inspect.iscoroutinefunction(backend_func):
                        return await backend_func()
                    return backend_func()
                forward_resource.__name__ = uri
                return forward_resource

            proxy.resource()(make_resource_forwarder(resource_func, resource_uri))

    return proxy

